/** Owner-only commissioning of the existing PRE policy and execute permission.
 * Independent field-review receipt is a real committed decision, never
 * generated by this command. No SOURCE enable, signer or provider credentials.
 * Exact Monday stage/package is reused. Unknown commit -> --inspect only.
 */
import {createHash} from "node:crypto";
import {execFileSync} from "node:child_process";
import {lstatSync,readFileSync,realpathSync} from "node:fs";
import {resolve,join} from "node:path";
import {fileURLToPath} from "node:url";
import {Pool,type PoolClient} from "pg";
import {bindMondayPolicyStage} from "./p6_nov20_finalize_recovered_policies_v39";
import {admitP6InertOwnerReadback} from "../scripts/v39_phase6_inert_release_stage_manual_v39.mjs";
import {p6SourceAuthorizationStageContentSha,verifyP6PostStageEvidenceOnlyMainAdvance} from "../scripts/v39_phase6_enable_source_owner_v39";
import {readP6MondayExactBridgeReview,verifyP6MondayRevisedExecutableBridge} from "../scripts/v39_phase6_revised_stage_executable_bridge_v39";
import {verifyP6ActualCommittedPlanParity} from "../scripts/v39_phase6_actual_release_candidate_export_v39";
import {inspectP5V0093IndependentExactPostStage} from "../server/lib/disruption/phase5V0093IndependentPostStageReadback_v39.mjs";
import {compilePhase7PrePolicyCommission,checkPhase7NativePrePolicySupport,installPhase7PrePolicyOnce,inspectPhase7PrePolicyCommission,type Phase7PrePolicyCommissionScope} from "../server/lib/disruption/phase7PrePolicyCommission_v39";
import {parsePhase7ProtectedPrePolicy} from "../server/lib/disruption/phase7ProtectedPreResolver_v39";
import {parseP7ReferenceLinkPolicy} from "../server/lib/disruption/phase7ExactPreLaneEvidenceAuthority_v39";
const REPO="HKcode22/ReplitTranvr",H=/^[a-f0-9]{64}$/,C=/^[a-f0-9]{40}$/;
export const P7_MONDAY_FIRST_SOURCE="2026-11-23T23:45:00.000Z",P7_MONDAY_AUTH_DEADLINE="2026-11-23T23:10:00.000Z",P7_MONDAY_OUTCOME_TAIL="2026-12-29T04:00:00.000Z";
const TERMS="data-collection/phase5/evidence/2026-11-19_aerodatabox_bounded_published_terms_source_use_review.md";
const HOLD=(s:string):never=>{throw Error("HOLD_P7_OWNER_POLICY_"+s)};
const need=(x:unknown,s:string)=>{if(!x)HOLD(s)};
const sha=(b:Buffer|string)=>createHash("sha256").update(b).digest("hex");
const digest=(x:unknown):x is string=>typeof x==="string"&&H.test(x)&&!/^([a-f0-9])\1{63}$/.test(x);
const at=(s:string)=>{const t=Date.parse(s);need(Number.isFinite(t)&&new Date(t).toISOString()===s,"CLOCK");return t};
const cmd=(c:string,a:string[])=>execFileSync(c,a,{encoding:"utf8",stdio:["ignore","pipe","ignore"],timeout:20000,maxBuffer:5*1024*1024}).trim();
const remote=()=>cmd("gh",["api","repos/"+REPO+"/git/ref/heads/main","--jq",".object.sha"]);
const gitBytes=(head:string,p:string)=>execFileSync("git",["show",head+":"+p],{stdio:["ignore","pipe","ignore"],timeout:20000,maxBuffer:2*1024*1024});
export type P7OwnerPolicyStageScope={stageCode:string;stageSha256:string;costSha256:string;manifestSha256:string;boundedTermsSha256:string};
export type P7OwnerPolicyDecisionScope=Phase7PrePolicyCommissionScope&{referencePolicyBytesSha256:string;operationalBridgeReviewSha256?:string};
export function validateP7OwnerPolicyDecision(raw:Buffer,expectedSha:string,stage:P7OwnerPolicyStageScope,policy:Buffer,now:Date):P7OwnerPolicyDecisionScope{
 need(Buffer.isBuffer(raw)&&raw.length>0&&raw.length<=16000&&digest(expectedSha)&&sha(raw)===expectedSha,"EXACT_COMMITTED_DECISION");
 const d=JSON.parse(raw.toString("utf8"));
 const keys=["schema","stageCode","stageSha256","costSha256","manifestSha256","boundedTermsSha256","rightsSha256","policyBytesSha256","policyReviewSha256","referencePolicyBytesSha256","validFromUtc","validUntilUtc","firstSourceUtc","outcomeTailUtc","reviewedAtUtc","reviewedBy","independentFieldProfileApproved","independentMappingAndReconstructionReviewApproved","originalScientificDesignPreserved","sourceUseDeferred","phase6PaidGo"];
 const bridged=d?.schema==="v39.phase7.pre-policy-owner-commission-review.v2";
 if(bridged)keys.push("operationalBridgeReviewSha256");
 need(d&&Object.keys(d).length===keys.length&&keys.every(k=>Object.hasOwn(d,k))&&(d.schema==="v39.phase7.pre-policy-owner-commission-review.v1"||bridged)&&(!bridged||digest(d.operationalBridgeReviewSha256))&&Object.entries(stage).every(([k,v])=>d[k]===v)&&C.test(stage.stageCode)&&[stage.stageSha256,stage.costSha256,stage.manifestSha256,stage.boundedTermsSha256,d.rightsSha256,d.policyBytesSha256,d.policyReviewSha256,d.referencePolicyBytesSha256].every(digest)&&sha(policy)===d.policyBytesSha256&&d.firstSourceUtc===P7_MONDAY_FIRST_SOURCE&&d.outcomeTailUtc===P7_MONDAY_OUTCOME_TAIL&&typeof d.reviewedBy==="string"&&/^[\x20-\x7e]{3,120}$/.test(d.reviewedBy)&&d.reviewedBy.trim().length>=3&&d.independentFieldProfileApproved===true&&d.independentMappingAndReconstructionReviewApproved===true&&d.originalScientificDesignPreserved===true&&d.sourceUseDeferred===true&&d.phase6PaidGo===false,"INDEPENDENT_SCOPE");
 const n=now.getTime();need(Number.isFinite(n)&&at(d.reviewedAtUtc)<=n&&at(d.reviewedAtUtc)<at(P7_MONDAY_AUTH_DEADLINE),"REVIEW_CLOCK");
 return {manifestSha256:d.manifestSha256,rightsSha256:d.rightsSha256,policyBytesSha256:d.policyBytesSha256,policyReviewSha256:d.policyReviewSha256,referencePolicyBytesSha256:d.referencePolicyBytesSha256,validFromUtc:d.validFromUtc,validUntilUtc:d.validUntilUtc,firstSourceUtc:d.firstSourceUtc,outcomeTailUtc:d.outcomeTailUtc,...(bridged?{operationalBridgeReviewSha256:d.operationalBridgeReviewSha256}:{})};
}
/** The one existing decision binds both PRE and reference-link policy bytes.
 * Check the actual producer routes and study validity BEFORE any owner SQL.
 * Purpose approval is not extended or inferred from this structural check. */
export function validateP7OwnerReferencePolicy(policy:Buffer,reference:Buffer,scope:Phase7PrePolicyCommissionScope&{referencePolicyBytesSha256:string}){
 need(Buffer.isBuffer(reference)&&reference.length>0&&reference.length<=15000&&digest(scope.referencePolicyBytesSha256)&&sha(reference)===scope.referencePolicyBytesSha256,"EXACT_REFERENCE_POLICY_BYTES");
 const env={V39_P5_MANIFEST_SHA256:scope.manifestSha256,V39_P5_RIGHTS_SHA256:scope.rightsSha256,
  P6_PHASE7_PRE_POLICY_BASE64:policy.toString("base64"),P6_PHASE7_PRE_PRESERVATION_POLICY_SHA256:scope.policyReviewSha256,
  P6_PHASE7_PRE_REFERENCE_LINK_POLICY_BASE64:reference.toString("base64"),P6_PHASE7_PRE_REFERENCE_LINK_POLICY_SHA256:scope.referencePolicyBytesSha256};
 const p=parsePhase7ProtectedPrePolicy(env);
 checkPhase7NativePrePolicySupport(p);
 const link=parseP7ReferenceLinkPolicy(env,p.profile.termsReviewSha256,p.dispositions);
 need(at(link.validFromUtc)<=at(scope.firstSourceUtc)&&at(link.validUntilUtc)>at(scope.outcomeTailUtc),"REFERENCE_STUDY_WINDOW");
 return {referencePolicyBytesSha256:scope.referencePolicyBytesSha256,referenceFieldCount:link.fields.length,providerCalls:0,databaseWrites:0,phase6PaidGo:false};
}
function ownPrivate(p:string,max=2*1024*1024){
 const f=resolve(p),s=lstatSync(f),home=realpathSync(process.env.HOME!);
 need(f.startsWith(home+"/.travnr-")&&realpathSync(f)===f&&s.isFile()&&!s.isSymbolicLink()&&s.nlink===1&&s.uid===process.getuid?.()&&(s.mode&0o077)===0&&s.size>0&&s.size<=max,"PRIVATE_FILE");
 return readFileSync(f);
}
async function main(){
 const [mode,dir,policyFile,referenceFile,decisionPath,decisionSha]=process.argv.slice(2);
 need(process.argv.length===8&&["--apply-reviewed","--inspect"].includes(mode)&&process.env.GITHUB_ACTIONS!=="true"&&process.env.ADB_AUTO_COLLECT==="0"&&process.env.V39_PHASE6_PROCESS_ARMED==="0"&&process.env.V39_PHASE6_OWNER_APPROVED==="0"&&process.env.NODE_TLS_REJECT_UNAUTHORIZED!=="0"&&![process.env.AERODATABOX_API_KEY,process.env.RAPIDAPI_KEY,process.env.AERODATABOX_WEBHOOK_SECRET,process.env.V39_DATABASE_RUNTIME_URL].some(Boolean),"OWNER_NO_PROVIDER_SCOPE");
 const head=cmd("git",["rev-parse","HEAD"]);
 need(C.test(head)&&head===remote()&&realpathSync(process.cwd())===realpathSync(cmd("git",["rev-parse","--show-toplevel"]))&&cmd("git",["status","--porcelain","--untracked-files=no"])==="","EXACT_CLEAN_MAIN");
 const root=resolve(dir),st=lstatSync(root);need(root.startsWith(realpathSync(process.env.HOME!)+"/.travnr-phase6-monday-")&&realpathSync(root)===root&&st.isDirectory()&&!st.isSymbolicLink()&&st.uid===process.getuid?.()&&(st.mode&0o077)===0,"PRIVATE_STAGE_DIRECTORY");
 const stage=ownPrivate(join(root,"new-stage-input.json"),48000),manifest=ownPrivate(join(root,"new-manifest.json")),cfg=ownPrivate(join(root,"new-config.json")),external=ownPrivate(join(root,"new-external.json")),timing=ownPrivate(join(root,"new-timing.json"));
 const pin=bindMondayPolicyStage(stage.toString("utf8"),manifest.toString("utf8"),cfg.toString("utf8"),external,timing);
 need(/^data-collection\/phase5\/evidence\/[A-Za-z0-9][A-Za-z0-9_.-]{0,180}\.json$/.test(decisionPath??""),"DECISION_PATH");
 const raw=gitBytes(head,decisionPath),policy=ownPrivate(policyFile,36000),scope=validateP7OwnerPolicyDecision(raw,decisionSha,{stageCode:pin.stageCode,stageSha256:pin.stageSha,costSha256:pin.costSha,manifestSha256:pin.manifestSha,boundedTermsSha256:sha(gitBytes(head,TERMS))},policy,new Date());
 need(raw.equals(readFileSync(decisionPath)),"DECISION_WORKTREE_DRIFT");
 const ancestor=(a:string,b:string)=>{try{execFileSync("git",["merge-base","--is-ancestor",a,b],{stdio:"ignore",timeout:10000});return true}catch{return false}};
 const diff=(end:string)=>cmd("git",["diff","--no-renames","--name-only",pin.stageCode,end]).split("\n").filter(Boolean);
 // v1 stays strictly evidence-only. A v2 independently reviewed PRE decision
 // must bind the exact operational bridge bytes before any owner SQL. This
 // is a disarmed commissioning scope, NOT an early SOURCE AUTH approval.
 if(scope.operationalBridgeReviewSha256){
  const {path:reviewPath,bytes:reviewBytes}=readP6MondayExactBridgeReview(scope.operationalBridgeReviewSha256,p=>gitBytes(head,p));
  need(sha(reviewBytes)===scope.operationalBridgeReviewSha256&&reviewBytes.equals(readFileSync(reviewPath)),"BRIDGE_BYTES_DRIFT");
  const reviewed=JSON.parse(reviewBytes.toString("utf8")).reviewedExecutableCommit;
  need(C.test(reviewed??""),"BRIDGE_COMMIT");
  verifyP6MondayRevisedExecutableBridge({stageCode:pin.stageCode,stageSha:pin.stageSha,costSha:pin.costSha,currentHead:head,reviewBytes,expectedOperationalEvidenceSha256:scope.operationalBridgeReviewSha256,now:new Date(),stageIsAncestor:ancestor(pin.stageCode,head),reviewedCommitIsAncestor:ancestor(pin.stageCode,reviewed)&&ancestor(reviewed,head),reviewedDiff:diff(reviewed),currentDiff:diff(head),readReviewedBlob:p=>cmd("git",["ls-tree",reviewed,"--",p]).split("\t")[0],readCurrentBlob:p=>cmd("git",["ls-tree",head,"--",p]).split("\t")[0]},stage.toString("utf8"),p6SourceAuthorizationStageContentSha(JSON.parse(stage.toString("utf8"))),pin.costSha);
 }else verifyP6PostStageEvidenceOnlyMainAdvance(pin.stageCode,head,diff(head),ancestor(pin.stageCode,head));
 verifyP6ActualCommittedPlanParity(pin.result,p=>gitBytes(head,p),p=>readFileSync(p));
 const compiled=compilePhase7PrePolicyCommission(policy,scope);
 const reference=validateP7OwnerReferencePolicy(policy,ownPrivate(referenceFile,15000),scope);
 const admitted=admitP6InertOwnerReadback({...process.env,V39_P5_APPROVED_CODE_SHA:pin.stageCode},stage.toString("utf8"),pin.stageSha,pin.costSha,pin.stageCode);
 const u=new URL(process.env.DATABASE_URL??"");need(decodeURIComponent(u.username)==="neondb_owner"&&u.searchParams.getAll("sslmode").length===1,"EXISTING_OWNER");
 const pool=new Pool({connectionString:u.toString(),max:2,connectionTimeoutMillis:8000,query_timeout:35000,application_name:"p7_pre_policy_owner_commission"});
 try{
  const independent=await inspectP5V0093IndependentExactPostStage(pool,admitted.input,admitted.review,admitted.freezeReview);
  need(independent.status==="INDEPENDENT_EXACT_B0062_V0093_POST_STAGE_READONLY_MATCH_NO_GO"&&independent.authorizationEnabled===false&&independent.exactReviewedStagePacketSha256===pin.stageSha&&independent.exactReviewedCostEnvelopeSha256===pin.costSha,"EXACT_DISABLED_STAGE_READBACK");
  if(mode==="--apply-reviewed"){
   need(process.env.P7_PRE_POLICY_OWNER_APPROVAL==="APPLY_EXACT_REVIEWED_PRE_POLICY_AND_NARROW_EXECUTE_NO_PROVIDER"&&Date.now()<at(P7_MONDAY_AUTH_DEADLINE)&&head===remote(),"EXPLICIT_OWNER_APPROVAL_AND_CLOCK");
   const guard=async(c:PoolClient)=>{
    const who=(await c.query("SELECT current_database() db,current_user actor,session_user login,current_setting('server_version_num')::int ver,current_setting('transaction_read_only') ro,pg_is_in_recovery() replica,pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='clean.adb_phase6_authorization'::regclass)) owner,clock_timestamp() at")).rows[0];
    need(who?.db==="neondb"&&who.actor==="neondb_owner"&&who.login===who.actor&&who.owner===who.actor&&who.ver>=160000&&who.ver<170000&&who.ro==="off"&&who.replica===false&&who.at instanceof Date&&who.at.getTime()<at(P7_MONDAY_AUTH_DEADLINE),"OWNER_ROLE_OR_CLOCK");
    const lock=(await c.query("SELECT pg_try_advisory_xact_lock(hashtext('v39-phase6-provider-mutation')::bigint) ok")).rows[0];need(lock?.ok===true,"PROVIDER_MUTATION_LOCK");
    await c.query("LOCK TABLE clean.adb_phase6_authorization,clean.adb_collection_meta,clean.adb_collection_subs,clean.adb_collection_batches,clean.adb_incident_stop,clean.adb_probe_budget_day,clean.phase5_fids_seven_rest_release_v39 IN SHARE ROW EXCLUSIVE MODE");
    const auth=(await c.query("SELECT authorization_id,manifest_sha256,calendar_hash,config_hash,code_sha,enabled,revoked_at_utc FROM clean.adb_phase6_authorization WHERE singleton_key=true")).rows;
    const a=auth[0];need(auth.length===1&&a.authorization_id===admitted.input.phase6AuthorizationId&&a.manifest_sha256===pin.manifestSha&&a.calendar_hash===pin.calendarSha&&a.config_hash===pin.configSha&&a.code_sha===pin.stageCode&&a.enabled===false&&a.revoked_at_utc===null,"EXACT_DISABLED_AUTH");
    const b=(await c.query("SELECT (SELECT count(*)::int FROM clean.adb_collection_subs WHERE ended_at IS NULL) subs,(SELECT count(*)::int FROM clean.adb_collection_batches WHERE status='ACTIVE' OR run_day_index IS NOT NULL) batches,(SELECT count(*)::int FROM clean.adb_incident_stop WHERE NOT resolved) incidents,(SELECT count(*)::int FROM clean.adb_probe_budget_day WHERE state='OPEN') budgets,(SELECT count(*)::int FROM clean.adb_collection_meta WHERE key=$1) source_enabled",[ "phase6_source_authorization_enabled:"+a.authorization_id])).rows[0];need(Object.values(b).every(n=>n===0),"ACTIVE_OR_UNRESOLVED_EXPOSURE");
    const m=(await c.query("SELECT value FROM clean.adb_collection_meta WHERE key=$1",["phase5_frozen_manifest:"+pin.manifestSha])).rows;
    const k=(await c.query("SELECT reviewed_cost_envelope_sha256 FROM clean.phase5_fids_seven_rest_release_v39 WHERE manifest_sha256=$1",[pin.manifestSha])).rows;
    need(m.length===1&&m[0].value===manifest.toString("utf8")&&k.length===1&&k[0].reviewed_cost_envelope_sha256===pin.costSha,"MANIFEST_OR_COST_DRIFT");
   };
   const receipt=await installPhase7PrePolicyOnce(pool,policy,scope,guard);console.log(JSON.stringify(receipt));
  }
  const final=await inspectPhase7PrePolicyCommission(pool,compiled);console.log(JSON.stringify({...final,manifestSha256:pin.manifestSha,stageSha256:pin.stageSha,costSha256:pin.costSha,decisionSha256:decisionSha,main:head,policyBytesSha256:scope.policyBytesSha256,referencePolicyBytesSha256:reference.referencePolicyBytesSha256,referenceFieldCount:reference.referenceFieldCount,operationalBridgeReviewSha256:scope.operationalBridgeReviewSha256??null}));
 }finally{await pool.end()}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))main().catch(e=>{const m=String(e?.message??"");console.error(/^HOLD_P7_[A-Z0-9_]+$/.test(m)?m:"HOLD_P7_OWNER_POLICY_REDACTED_INSPECT_NO_REPLAY");process.exitCode=2});
